import os
import torch
import numpy as np
import random


class Config:
    # =========================================================================
    # Directories & Paths
    # =========================================================================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"
    # Output directory for checkpoints and logs specific to Idea 11
    OUTPUT_DIR = "./working/idea_11"

    # Metadata files generated by the provided script
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Compute & Hardware
    # =========================================================================
    # 12 vCPUs available
    NUM_WORKERS = 12
    # A100 GPU available
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # =========================================================================
    # Data Configuration
    # =========================================================================
    IMG_SIZE = 384
    NUM_CLASSES = 5

    # =========================================================================
    # Model Configuration (Tri-Modal Heterogeneous Ensemble)
    # =========================================================================
    # 1. Supervised Attention Expert (ViT)
    # 2. Masked Image Modeling Expert (BEiT)
    # 3. Modern Convolutional Expert (ConvNeXt)
    MODELS = [
        "vit_base_patch16_384",
        "beit_base_patch16_384",
        "convnext_base_384_in22ft1k",
    ]

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    SEED = 42
    EPOCHS = 12  # Fixed duration, no early stopping

    # Batch size for A100 40GB (384x384 resolution)
    # 32 is a safe conservative estimate for Base models with AMP
    BATCH_SIZE = 32

    # Optimizer & Scheduler
    LR = 1e-4
    MIN_LR = 1e-6
    WEIGHT_DECAY = 0.05

    # =========================================================================
    # Regularization & Augmentation
    # =========================================================================
    LABEL_SMOOTHING = 0.1
    DROP_PATH_RATE = 0.2  # Stochastic Depth

    # MixUp / CutMix
    MIXUP_ALPHA = 0.8
    CUTMIX_ALPHA = 1.0
    MIXUP_PROB = 1.0  # Probability to apply mixing

    # Test Time Augmentation
    TTA_STEPS = 4

    # =========================================================================
    # Utility Functions
    # =========================================================================
    @staticmethod
    def setup(seed=42):
        """
        Sets up the environment:
        1. Creates necessary directories.
        2. Sets random seeds for reproducibility.
        """
        # Create directories
        os.makedirs(Config.OUTPUT_DIR, exist_ok=True)
        os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)

        # Set seeds
        Config.SEED = seed
        random.seed(seed)
        os.environ["PYTHONHASHSEED"] = str(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

        # Print config info
        print(f"Config Setup Complete.")
        print(f"  Device: {Config.DEVICE}")
        print(f"  Output Dir: {Config.OUTPUT_DIR}")
        print(f"  Models: {Config.MODELS}")
